css:
.loader {
  position: relative;
  width: 48px;
  height: 34px;
  animation: send 1.6s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  inset: 0;
  background: #6366f1;
  border-radius: 3px;
}
.loader::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 62%;
  background: #4338ca;
  border-radius: 3px 3px 0 0;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
.loader i {
  position: absolute;
  left: -12px;
  top: 50%;
  width: 10px;
  height: 2px;
  margin-top: -1px;
  border-radius: 2px;
  background: #c7d2fe;
  box-shadow: -2px -7px 0 #c7d2fe, -2px 7px 0 #c7d2fe;
}
@keyframes send {
  0%, 100% { transform: translate(0, 0); }
  50% { transform: translate(6px, -6px); }
}
